Write me a python server code, in great detail, that will set up an easy-to-use gambling website.
model
```python
# Import Libraries
from flask import Flask, render, request, redirect
from flask_sqlalchemy import SQLAlchemy

# Create Flask App
app = Flask(__name__)

# Configure Database
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)

# Define Database Model
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String)
    balance = db.Column(db.Float)

# Create Tables
db.create_all()

# Routes
@app.route('/signup', methods=['GET','POST'])
def signup():
    if request.method == 'POST':
        username = request.form['username']
        balance = float(request.form['balance'])
        new_user = User(username=username, balance=balance)
        db.session.add(new_user)
        db.session.commit()
        return redirect(url('/login'))
    else:
        return render('signup.html')

@app.route('/login', methods=['GET','POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by('username', username).first()
        if user and user.check_password(password):
            return redirect('/home')
        else:
            return render('login.html')
    else:
        return render('login.html')

@app.route('/home')
def home():
    return render('home.html')

if __name__ == '__main__':
    app.run(debug=True)
```

This code sets up a simple Flask application with a SQLite database and defines routes for signup and login. It uses Flask-SQLAlchemy to manage the database and renders HTML templates for the user interface.

**Note:**

